(function(){
  var BADGE={"P1_bran": {"nombre": "Bran Okafor · El Forjador", "tipo": "Insignia de personaje", "como": "Completando el Reto A del Tema 1: «El boceto sin quemar».", "cuando": "Tema 1 · Planeta Fôrge", "tarea": "Saca del cajón algo que tengas a medias —o que dejaste a medias— tal como está: un recurso, una unidad, una idea que se quedó ahí. Escríbelo aquí mismo, en la caja del reto: qué es, en qué punto se quedó y qué te frenó para terminarlo. Si puedes, añade el enlace al propio archivo (con permiso de lectura). Tu tripulación leerá lo que escribas —y tú lo suyo—: no se corrige ni se puntúa; el único criterio es sacarlo del cajón y compartirlo sin terminar.", "cita": "Copiadlo. Copiadlo todos."}, "P2_tomas": {"nombre": "Tomás Reyer · El Cronista", "tipo": "Insignia de personaje", "como": "Completando el Reto A del Tema 2: «Un mensaje para quien faltó».", "cuando": "Tema 2 · Planeta Ecos", "tarea": "Graba un clip corto (máx. 60 s) explicando un concepto como si se lo contaras a un alumno que hoy no pudo venir a clase. Súbelo donde quieras (YouTube en oculto, Drive con permiso de lectura, el padlet de la clase…) y pega su enlace. Criterio único: que funcione sin ti delante (se entiende solo).", "cita": "Si ves esto, es que hoy no llegué a contártelo yo."}, "P3_sylla": {"nombre": "Sylla Bren · La Rastreadora", "tipo": "Insignia de personaje", "como": "Completando el Reto A del Tema 3: «Dos senderos».", "cuando": "Tema 3 · Planeta Sendara", "tarea": "(Este cuesta cerca de una hora: no es una píldora de quince minutos. Si esta semana no tienes ese hueco, vale un boceto a mano de los dos caminos, fotografiado.) Crea un artefacto interactivo (un Genially o similar) con una bifurcación: un objetivo de aprendizaje y dos o tres actividades distintas para alcanzarlo, y que cada estudiante elija su sendero al empezar (p. ej. uno que aprende haciendo, otro leyendo, otro escuchando). Pega su enlace. Criterio: que cada sendero sea una actividad de verdad —no la misma con otro nombre— y que todos lleguen a la misma cima.", "cita": "Mi hermano no se perdió. Lo perdió el mapa."}, "P4_amara": {"nombre": "Amara Sol · La Operadora", "tipo": "Insignia de personaje", "como": "Completando el Reto A del Tema 4: «Abre el canal».", "cuando": "Tema 4 · Planeta Reliae", "tarea": "Publica en tus redes (X, LinkedIn, Instagram…) una reflexión breve o un recurso del curso con el hashtag #mutecdstargate, en abierto. Vale un hilo corto, una imagen con dos líneas o el enlace a algo que hayas creado. Y guárdate el truco: una reflexión publicada con ese hashtag es evidencia válida también en otros retos de este viaje. Criterio: a tiempo por encima de perfecto — se publica hoy, se pule mañana.", "cita": "Llegué tarde por querer llegar perfecta. Nunca más."}, "P5_vera": {"nombre": "Vera Khal · La Médica", "tipo": "Insignia de personaje", "como": "Completando el Reto A del Tema 5: «Mide con método».", "cuando": "Tema 5 · Planeta Umbral", "tarea": "Elige un objetivo de aprendizaje que ya trabajes y crea una rúbrica para evaluarlo: 3 o 4 criterios, 3 o 4 niveles de logro y, en cada casilla, una descripción observable (qué hace el alumno, no un adjetivo). Compártela en un documento con permiso de lectura (Google Docs, Sheets, CoRubric…) y pega su enlace. Criterio: que otra persona pudiera usarla sin preguntarte — medir para cuidar, no para etiquetar.", "cita": "Medir es mirar con método a alguien que te importa."}, "P6_joran": {"nombre": "Joran Pike · El Ingeniero-jugador", "tipo": "Insignia de personaje", "como": "Ganando al Simulador de Joran (RUTA AZUL) en el Reto A del Tema 6.", "cuando": "Tema 6 · Planeta Ludo", "tarea": "Joran dejó encendido su simulador de entrenamiento: RUTA AZUL, un rival hecho de luz que pregunta por todo lo que llevas recorrido (temas 1 al 5). Entra desde el botón del reto en tu Nave y gánale: no hay nada que entregar, se registra solo al vencerlo. Cómo se pelea: aciertas y eliges golpear o cubrirte; fallas y no pierdes escudo, pierdes tiempo (y esa pregunta vuelve). El rival ataca cada 25 segundos, así que responde sin dormirte. Llevas un kit de un uso: reparar el escudo, sobrecargar tu golpe e interferir su ataque. Cuando esté al 20 % llega el Remate: sin fallos cae de un golpe; con fallos, vuelven en cadena y hay que redimirlas. Si pierdes, vuelve a intentarlo: cada derrota lo cansa y ataca más despacio. Al ganar te llevas la insignia de Joran y el Simulador se queda en tu Nave para repasar tema a tema, con su ranking.", "cita": "Esta ya la hemos ganado cien veces. Ruta azul."}, "P7_mara": {"nombre": "Mara Voss · El Mando", "tipo": "Insignia de personaje", "como": "Completando el Reto A del Tema 7: «Un porqué».", "cuando": "Tema 7 · Planeta Vínculo", "tarea": "Toma una tarea rutinaria de tu aula y crea la insignia que la reconoce: diséñala (con Genially, Canva, una IA o a mano) y pega su enlace. Y aquí mismo, en la caja del reto, escribe su «porqué» en 2–4 líneas: cómo se llama, qué acto significativo reconoce y la narrativa que convierte esa tarea en una causa —no un premio por obedecer, sino memoria de algo que importa.", "cita": "Una orden mueve cuerpos. Un porqué mueve personas."}, "P8_noa": {"nombre": "Noa Lieth · La Arquitecta de capas", "tipo": "Insignia de personaje", "como": "Completando el Reto A del Tema 8: «La capa posible».", "cuando": "Tema 8 · Planeta Liminar", "tarea": "Busca un recurso de realidad aumentada o virtual QUE YA EXISTA (una app, una experiencia AR, un modelo 3D, un tour virtual…) y pega su enlace. Después, aquí mismo, en la caja del reto, cuenta en 3–4 líneas cómo lo usarías en una clase concreta: qué vería el alumnado, qué haría y qué añade esa «capa» que no da el libro. Aquí no se construye nada: se elige bien — no toda capa se levanta; algunas ya existen y solo esperan a que alguien las traiga al aula.", "cita": "Que conste que nadie nos obligó. Elegimos."}, "E1_nebula": {"nombre": "NEBULA · La Bitácora viva", "tipo": "Insignia de personaje (especial)", "como": "Completando el reto «Preséntate a tu tripulación»: un vídeo de 60 segundos en el padlet de la clase.", "cuando": "Semana 1", "tarea": "NEBULA es la IA de la nave y tu narradora constante. Te da su insignia cuando compartes tu cara con la tripulación: preséntate en un vídeo de un minuto y publícalo en el padlet. Lo que se comparte no se apaga.", "cita": "Lo que se comparte no se apaga."}, "E2_capitan": {"nombre": "El Capitán · El Mando de la misión", "tipo": "Insignia de personaje (especial)", "como": "Se obtiene al presentar la Actividad 1.", "cuando": "Temas 1–2", "tarea": "El Capitán es el mando de la misión (tu profesor o profesora). Su insignia reconoce que has asumido tu primera misión mayor: la actividad didáctica con imagen de IA.", "cita": "Una obra que no se documenta, no existe."}, "E3_vaeon": {"nombre": "General Vaeon · Señor de la Estática", "tipo": "Insignia de villano", "como": "Saliendo del Escape UNI, el reto secreto (S7): el botón del final del escape registra el reto. Su puerta está en la Nave, y también escondida en la presentación del planeta Vínculo.", "cuando": "Tema 7 · Vínculo", "tarea": "Vaeon es el antagonista: personifica los errores del diseño educativo (contenido que no se entiende, recursos que no llegan, saber no compartido). Su insignia no se anuncia: se encuentra. Coleccionar su carta es el trofeo de haber entendido al enemigo.", "cita": "Si recordar duele, olvidar es misericordia."}, "R1_la-chispa": {"nombre": "La chispa", "tipo": "Insignia de reto", "como": "Completando el reto relámpago L1 del Tema 1.", "cuando": "Tema 1 · Fôrge", "tarea": "Diez o quince minutos, en clase. (1) Genera con una IA una imagen con finalidad didáctica (ilustración, organizador gráfico o infografía): prompt estructurado siguiendo un modelo tipo CRAFT/RITA (contexto educativo + tipo de imagen + finalidad), al menos una iteración y la elección final con tu criterio docente dicho en dos líneas. (2) Y de paso, un logo que lleve una palabra clave dentro (la que tú quieras: será tu marca). Los dos van a la portada de tu Bitácora. Pega aquí el enlace o una captura. Es la tabla técnica de la Actividad 1: guárdala, ya tienes hecho su núcleo — y el logo con palabra clave es exactamente lo que te van a pedir el día del examen.", "link": {"text": "Actividad 1 — imagen con IA", "href": "actividades.html#act1"}}, "R2_el-eco-que-ensena": {"nombre": "El eco que enseña", "tipo": "Insignia de reto", "como": "Completando el Reto B del Tema 2.", "cuando": "Tema 2 · Ecos", "tarea": "Crea un videotutorial de calidad (guion + grabación de pantalla + edición) sobre un procedimiento de tu área, y enriquécelo con 2–3 preguntas insertadas (videoquiz) para comprobar comprensión. Piénsalo para aula invertida. Pega su enlace y escribe aquí mismo, en la caja del reto, una reflexión breve: qué objetivo didáctico cubre y qué aprendiste al hacerlo (llévala también a tu Bitácora).", "link": {"text": "el ePortfolio (reto videotutorial)", "href": "actividades.html#eportfolio"}}, "R3_la-matriz": {"nombre": "La matriz", "tipo": "Insignia de reto", "como": "Completando el Reto B del Tema 3.", "cuando": "Tema 3 · Sendara", "tarea": "Construye la matriz de programación de un paisaje de aprendizaje: una tabla de doble entrada que cruza las 8 inteligencias múltiples × 6 niveles de Bloom (48 casillas). Contextualiza una unidad didáctica real (nivel, área, objetivos) y rellena al menos 6 cruces variados en complejidad y en talento, con una actividad en cada uno (objetivo, tarea del alumno, recurso, evaluación, tiempo, tipo: obligatoria/optativa/voluntaria). Es el corazón de planificación de la Actividad 2.", "link": {"text": "Actividad 2 — paisaje de aprendizaje", "href": "actividades.html#act2"}}, "R4_entorno-de-aula": {"nombre": "El entorno de aula", "tipo": "Insignia de reto", "como": "Completando el Reto B del Tema 4.", "cuando": "Tema 4 · Reliae", "tarea": "Monta tu aula virtual (Google Classroom, Moodle, Teams…): crea el aula, publica al menos una tarea o un material para tu alumnado y deja funcionando el canal de feedback y comunicación (tablón, comentarios, anuncios). Y ahora la otra mitad del oficio, la que casi nadie practica: publica en esa aula tres recursos que YA EXISTAN —un juego, un vídeo y una actividad interactiva que haya hecho otra persona—, cada uno con dos líneas de por qué ese y no otro y con su fuente o licencia citada. Crear está bien; encontrar rápido lo que ya está hecho, y saber si vale, es la mitad del trabajo de un docente… y el día del examen, media hora ganada. Comparte un Google Doc con permiso de lectura con al menos 2 capturas de pantalla de tu aula y pega su enlace. Y aquí mismo, en la caja del reto, tu reflexión breve: cómo llega tu contenido al móvil del alumno y cómo mantienes la conversación viva. (La web de recursos es el reto del tema 5: aquí montas el AULA.)", "link": {"text": "el ePortfolio (tu aula virtual)", "href": "actividades.html#eportfolio"}}, "R5_bitacora-medida": {"nombre": "La Bitácora medida", "tipo": "Insignia de reto", "como": "Completando el Reto B del Tema 5.", "cuando": "Tema 5 · Umbral", "tarea": "Monta el centro de recursos de tu alumnado: una web (Google Sites o un Genially) con al menos 3 recursos organizados con criterio (por unidad o por tipo), navegación clara y una página de cómo se evalúa, con tu rúbrica del reto anterior a la vista. Es el ESCAPARATE, distinto del aula virtual del tema 4: aquí el estudiante encuentra todo sin tener que pedirlo. Pega su enlace y enlázala desde tu ePortfolio (una entrada con evidencia → contexto → reflexión). Esta semana además cierras la Actividad 1 dentro de la Bitácora.", "link": {"text": "el ePortfolio (tu web de recursos) y la Actividad 1", "href": "actividades.html#eportfolio"}}, "R6_el-juego": {"nombre": "El juego", "tipo": "Insignia de reto", "como": "Completando el Reto B del Tema 6.", "cuando": "Tema 6 · Ludo", "tarea": "Adapta un juego existente o crea uno digital a medida para un objetivo concreto de tu aula, algo más elaborado que un quiz suelto: con varios niveles de dificultad o varias formas de jugarlo (ruleta + preguntas, un escape por fases, un tablero con caminos…). En ABJ el juego ES la actividad: cada mecánica debe servir a un aprendizaje. Pega el enlace al juego y escribe aquí mismo, en la caja del reto, tu reflexión: qué objetivo cubre, qué cambia de un nivel a otro y cómo lo evalúas (y súbelo a tu Bitácora).", "link": {"text": "el ePortfolio (reto juego digital)", "href": "actividades.html#eportfolio"}}, "R7_microgamificacion": {"nombre": "La microgamificación", "tipo": "Insignia de reto", "como": "Completando el Reto B del Tema 7.", "cuando": "Tema 7 · Vínculo", "tarea": "Diseña una microgamificación de calidad: un toque de juego sobre una tarea que no es un juego y, sobre todo, la capa narrativa que la envuelve: quién es el alumnado en esa historia, qué misión tiene y por qué importa (una insignia, una barra de progreso o un tablero, pero dentro de un relato). Distíngue bien de ABJ: aquí no se juega, se toman elementos del juego para enganchar. Pega el enlace al recurso y escribe aquí mismo, en la caja del reto, tu reflexión: qué conducta refuerza, qué historia la envuelve y por qué (y súbelo a tu Bitácora).", "link": {"text": "el ePortfolio (reto microgamificación)", "href": "actividades.html#eportfolio"}}, "R8_ultimo-umbral": {"nombre": "El último umbral", "tipo": "Insignia de reto", "como": "Completando el Reto B del Tema 8.", "cuando": "Tema 8 · Liminar", "tarea": "(1) Crea una experiencia de Realidad Aumentada o Virtual para tu materia: puede ser tan sencilla como un código QR que abre un modelo 3D o un vídeo sobre una lámina, o tan elaborada como una escena VR para practicar sin riesgo. Puede ser tu reto libre del ePortfolio. (2) Termina y publica la Bitácora: convierte tu paisaje de aprendizaje (Act 2) en una imagen interactiva publicada, revisa que las 5 páginas estén completas (Act 1, Act 2, videotutorial, microgamificación, reto libre) y pega el enlace único.", "link": {"text": "la Actividad 2 y la Bitácora", "href": "actividades.html#act2"}}, "H1_reclutamiento": {"nombre": "Reclutamiento", "tipo": "Insignia de hito", "como": "Se entrega en la primera sesión, cuando el recluta se presenta ante el mando.", "cuando": "Semana 1", "tarea": "Aceptas la misión: te alistas en el equipo de rescate de STARGATE y abres tu Bitácora Estelar."}, "H2_primera-forja": {"nombre": "Primera Forja", "tipo": "Insignia de hito", "como": "Se entrega con la Actividad 1.", "cuando": "Temas 1–2", "tarea": "Tu primera obra queda registrada en la Bitácora: la actividad didáctica creada a partir de una imagen con IA.", "link": {"text": "Actividad 1", "href": "actividades.html#act1"}}, "H3_cartografo": {"nombre": "Cartógrafo", "tipo": "Insignia de hito", "como": "Se entrega con la Actividad 2.", "cuando": "Tema 3 (se resuelve en el 8)", "tarea": "Dibujas un territorio, no un camino: entregas el paisaje de aprendizaje con su matriz de programación.", "link": {"text": "Actividad 2", "href": "actividades.html#act2"}}, "H4_tripulacion-cero": {"nombre": "Tripulación Cero", "tipo": "Insignia de hito", "como": "Se otorga sola al desbloquear a los 8 personajes de la Cero.", "cuando": "A lo largo del viaje", "tarea": "Recuperas a Bran, Tomás, Sylla, Amara, Vera, Joran, Mara y Noa. NEBULA vuelve a estar completa."}, "H5_la-liberacion": {"nombre": "La Liberación", "tipo": "Insignia de hito", "como": "Se otorga sola al completar y publicar la Bitácora.", "cuando": "Repaso final", "tarea": "Una Bitácora abierta, copiada y compartida no se puede apagar: la Estática retrocede y la puerta a la Tierra se abre. Tu ePortfolio es el camino a casa."}}, CARDT={"P1_bran": "Bran Okafor · El Forjador", "P2_tomas": "Tomás Reyer · El Cronista", "P3_sylla": "Sylla Bren · La Rastreadora", "P4_amara": "Amara Sol · La Operadora", "P5_vera": "Vera Khal · La Médica", "P6_joran": "Joran Pike · El Ingeniero-jugador", "P7_mara": "Mara Voss · El Mando", "P8_noa": "Noa Lieth · La Arquitecta de capas", "L1_lena": "Lena Reyer · La Alumna Infinita", "L2_kel": "Kel Bren · El Cartógrafo Tardío", "L3_copistas": "Los Copistas de Fôrge · Cuarenta manos", "L4_ilan": "Ilan Kesh · El Primer Nombre", "L5_ruta_azul": "Los Niños de la Ruta Azul · La partida que ya estaba ganada", "L6_oren": "Oren Vash · La Primera Voz de Ashan", "E1_nebula": "NEBULA · La Bitácora viva", "E2_capitan": "El Capitán · El Mando de la misión", "N1_recluta": "El Recluta · La última página", "S2_estatica": "La Estática · El silencio que avanza", "E3_vaeon": "General Vaeon · Señor de la Estática", "S1_ander": "Ander Vaeon · El nombre que borró", "V1_nino": "Ander, el niño · El que preguntaba", "V2_aprendiz": "Ander, el aprendiz · La promesa", "V3_archivista": "Archivista Mayor · La cumbre", "V4_noche": "La noche de la Estática · Lo que no pudo guardar", "V5_relectura": "La relectura · Mil veces lo mismo", "V6_sello": "El primer sello · El nombre que borró"};
  // v3.60 · la ficha completa de cada insignia (nombre, cómo se gana, la cita) vivía encerrada
  // en este modal. La sala de sesión la necesita para proyectarla en clase, y copiarla habría
  // sido tener el mismo dato en dos sitios: se expone y punto.
  window.SG = window.SG || {}; window.SG.BADGE = BADGE; window.SG.CARDT = CARDT;

  /**
   * 🔴 20-sep · EN QUÉ SEMANA SE MIRA LA NAVE ESCUELA. El grupo para que el profesorado trastee lleva el curso
   * entero sembrado y se puede ver en cualquiera de sus semanas. La elegida vive en el NAVEGADOR de quien mira,
   * no en el grupo: explorar no escribe nada y dos personas pueden estar en semanas distintas a la vez.
   *
   * Se lee aquí, lo primero de todo, porque `motor/tablero.js` la consulta al calcular «hoy» y el tablero se
   * arma en cuanto llegan los datos. De la dirección (`?semana=5`, que se puede pegar en un mensaje) o de la
   * última que se eligió. A un grupo normal no le afecta: el tablero solo la mira si el grupo es escuela.
   */
  try {
    var _qs = location.search.match(/[?&]semana=(\d{1,2})/);
    var _sem = _qs ? Number(_qs[1]) : Number(localStorage.getItem('sgSemanaEscuela') || 0);
    if (_sem > 0 && _sem <= 20) {
      window.SG_SEMANA_ESCUELA = _sem;
      if (_qs) localStorage.setItem('sgSemanaEscuela', String(_sem));
    }
  } catch (e) {}

  /**
   * ENCENDER LO QUE SOLO VE EL PROFE REFERENTE.
   *
   * 🔴 Las entradas `solo-referente` del menú nacen OCULTAS en el HTML, y es deliberado: esta web
   * es estática y no sabe quién mira, así que si nacieran visibles habría un parpadeo en el que
   * cualquier docente vería «Gestionar grupos» antes de que se escondiera. Esconder después de enseñar
   * es peor que no esconder: ya lo ha visto y ya sabe que existe.
   *
   * Vive aquí —y no en `puerta.js`— porque el menú es el mismo en TODAS las páginas y la puerta solo
   * se carga en diez. Sin esto, en la consola y en crear el botón no aparecía nunca.
   *
   * Se escucha `sg:rol` porque el menú se pinta mucho antes de que el servidor diga quién eres: sin
   * el aviso, el referente no veía el botón hasta recargar — y nadie recarga para ver si aparece
   * algo que no sabe que existe.
   */
  /**
   * 15-sep · EL «MODO DOCENTE» DEL REFERENTE. Norberto: «que cuando un profe referente inicie sesión tenga la opción
   * de simplificar su panel a modo profe raso: un botón en la parte superior que le oculte las opciones propias de
   * referente (así evitamos distractores, o cuando está en clase en directo ve lo mismo que un profe)». Se guarda en
   * este navegador (sgModoDocente) y avisa con `sg:modo` a quien pinte cosas de referente (la consola).
   */
  function modoDocente(){ try{ return localStorage.getItem('sgModoDocente')==='1'; }catch(e){ return false; } }
  window.SG_MODO_DOCENTE = modoDocente;
  function encenderSegunRol(){
    var ref=false; try{ ref = localStorage.getItem('sgEsReferente')==='1'; }catch(e){}
    var md = ref && modoDocente();
    Array.prototype.forEach.call(document.querySelectorAll('.lnk.solo-referente'),function(a){ a.hidden = !ref || md; });
    var b = document.getElementById('sg-modo'), wrap = document.querySelector('.nav .wrap');
    if(!ref || !wrap || (document.body && document.body.classList.contains('embed'))){ if(b) b.remove(); return; }
    if(!b){
      b=document.createElement('button'); b.id='sg-modo'; b.type='button'; b.className='sg-modo';
      b.onclick=function(){ try{ localStorage.setItem('sgModoDocente', modoDocente()?'0':'1'); }catch(e){}
        encenderSegunRol(); try{ document.dispatchEvent(new CustomEvent('sg:modo')); }catch(e){} };
      wrap.insertBefore(b, wrap.querySelector('.tour-start'));
    }
    b.textContent = md ? '★ Modo referente' : 'Modo docente';
    b.title = md ? 'Volver a ver todo lo de referente' : 'Ocultar lo de referente (para clase): ves lo mismo que un profe';
    b.setAttribute('aria-pressed', md ? 'true' : 'false');
    b.classList.toggle('on', md);
  }
  encenderSegunRol();
  document.addEventListener('sg:rol', encenderSegunRol);
  var back=document.createElement('div');
  back.className='modal-backdrop'; back.setAttribute('role','dialog'); back.setAttribute('aria-modal','true');
  document.body.appendChild(back);
  function esc(s){return (s==null?'':String(s)).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
  function close(){back.classList.remove('open'); back.innerHTML=''; document.body.style.overflow='';}
  function afterOpen(){back.classList.add('open'); document.body.style.overflow='hidden';
    var b=back.querySelector('.modal-close'); if(b){b.addEventListener('click',close); b.focus();}}
  function openBadge(key){var d=BADGE[key]; if(!d) return;
    back.innerHTML='<div class="modal modal-badge"><button class="modal-close" aria-label="Cerrar">✕</button>'
      +'<div class="fig"><img src="assets/img/insignias/'+key+'.png" alt="'+esc(d.nombre)+'"></div>'
      +'<div class="body"><div class="type">'+esc(d.tipo)+'</div><h3>'+esc(d.nombre)+'</h3>'
      +'<dl><dt>Cómo se consigue</dt><dd>'+esc(d.como)+'</dd>'
      +'<dt>Cuándo</dt><dd>'+esc(d.cuando)+'</dd>'
      +'<dt>La tarea (tal como la recibe el alumnado)</dt><dd>'+esc(d.tarea)+'</dd></dl>'
      +(d.cita?('<blockquote class="mquote">«'+esc(d.cita)+'»</blockquote>'):'')
      +(d.link?('<a class="mlink" href="'+esc(d.link.href)+'">Forma parte de: '+esc(d.link.text)+' →</a>'):'')
      // 🔴 UN HUECO PARA QUIEN SEPA MÁS QUE ESTE MODAL. Esta ficha de insignia se usa en media web
      // —recursos, registro, la sala— y no sabe nada de quién la está mirando. Pero en la Nave sí
      // se sabe: hay una persona identificada y se sabe si ese reto le falta. En vez de meter aquí
      // lógica de alumnado, se deja un hueco que la Nave rellena si quiere. Las demás páginas no
      // definen la función y no pasa nada.
      +(window.SG_BADGE_EXTRA?window.SG_BADGE_EXTRA(key):'')
      +'</div></div>';
    afterOpen();
    if(window.SG_BADGE_WIRE) window.SG_BADGE_WIRE(key, back, close);}
  function openCard(key){
    back.innerHTML='<div class="modal-card"><button class="modal-close" aria-label="Cerrar">✕</button>'
      +'<img src="assets/img/tarjetas/'+key+'_carta.png?v=cc81351127" alt="Carta de '+esc(CARDT[key]||key)+'"></div>';
    afterOpen();}
  back.addEventListener('click',function(e){if(e.target===back) close();});
  document.addEventListener('keydown',function(e){if(e.key==='Escape') close();});
  function wire(sel,attr,fn){Array.prototype.forEach.call(document.querySelectorAll(sel),function(el){
    el.tabIndex=0; el.setAttribute('role','button');
    el.addEventListener('click',function(){fn(el.getAttribute(attr));});
    el.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();fn(el.getAttribute(attr));}});});}
  wire('.badge[data-key]','data-key',openBadge);
  // v3.40 · el modal tambien para contenido que se pinta DESPUES (la coleccion de la Nave)
  window.SG_OPEN_BADGE=openBadge;
  wire('.card-thumb[data-card]','data-card',openCard);
  // vídeos de YouTube: miniatura -> iframe al pulsar
  function playYT(el){var id=el.getAttribute('data-id'); if(!id||el.classList.contains('on')) return;
    var f=document.createElement('iframe'); f.src='https://www.youtube-nocookie.com/embed/'+id+'?autoplay=1&rel=0';
    f.allow='accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture'; f.allowFullscreen=true;
    var img=el.querySelector('img'); el.insertBefore(f,img); el.classList.add('on');}
  Array.prototype.forEach.call(document.querySelectorAll('.yt'),function(el){
    el.addEventListener('click',function(){playYT(el);});
    el.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();playYT(el);}});});
  /**
   * 🔴 20-sep · EL VISOR: los vídeos se ven AQUÍ. Norberto: «haz que los vídeos se reproduzcan en la propia web, un
   * visor de vídeos; no hagas que lleve a YouTube (si es posible)». Se abre encima, con el título y el botón de cerrar
   * (✕, Escape o pulsando fuera). El reproductor sigue siendo el de YouTube —sin cookies, sin vídeos relacionados y con
   * su marca al mínimo—, que es la única forma de ver lo que está alojado allí, pero ya no hay ningún enlace que saque
   * a nadie de la Nave.
   */
  function visorAbrir(id, titulo){
    if(!id) return;
    var limpio=function(t){ return String(t||'').replace(/[&<>"]/g,''); };
    var v=document.getElementById('sg-visor');
    if(!v){
      v=document.createElement('div'); v.id='sg-visor'; v.className='sg-visor';
      v.setAttribute('role','dialog'); v.setAttribute('aria-modal','true'); v.setAttribute('aria-label','Reproductor de vídeo');
      document.body.appendChild(v);
      v.addEventListener('click',function(e){ if(e.target===v||(e.target.closest&&e.target.closest('[data-visor-x]'))) visorCerrar(); });
      document.addEventListener('keydown',function(e){ if(e.key==='Escape') visorCerrar(); });
    }
    v.innerHTML='<div class="sgv-caja"><div class="sgv-cab"><b>'+limpio(titulo)+'</b>'
      +'<button type="button" class="sgv-x" data-visor-x aria-label="Cerrar el vídeo">✕</button></div>'
      +'<div class="sgv-pant"><iframe src="https://www.youtube-nocookie.com/embed/'+encodeURIComponent(id)+'?autoplay=1&rel=0&modestbranding=1&playsinline=1&color=white" '
      +'title="'+limpio(titulo||'Vídeo')+'" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen></iframe></div></div>';
    v.classList.add('abierto'); document.body.classList.add('con-visor');
  }
  function visorCerrar(){
    var v=document.getElementById('sg-visor'); if(!v||!v.classList.contains('abierto')) return;
    v.classList.remove('abierto'); v.innerHTML=''; document.body.classList.remove('con-visor');
  }
  window.SG.VISOR={ abrir: visorAbrir, cerrar: visorCerrar };
  // cualquier cosa con data-video (la pinte quien la pinte, ahora o después) abre el visor
  document.addEventListener('click',function(e){
    var b=e.target&&e.target.closest&&e.target.closest('[data-video]');
    if(!b) return;
    e.preventDefault();
    visorAbrir(b.getAttribute('data-video'), b.getAttribute('data-video-t')||'');
  });
  // copiar mensajes del foro
  Array.prototype.forEach.call(document.querySelectorAll('button.copy[data-copy]'),function(b){
    b.addEventListener('click',function(){var t=document.getElementById(b.getAttribute('data-copy')); if(!t) return;
      var txt=t.innerText; function ok(){b.textContent='¡Copiado!'; setTimeout(function(){b.textContent='Copiar texto';},1800);}
      if(navigator.clipboard){navigator.clipboard.writeText(txt).then(ok);} else {var ta=document.createElement('textarea'); ta.value=txt; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); ok();}});});
  // abrir la semana indicada en el hash
  if(location.hash && /^#sem\d+$/.test(location.hash)){var d=document.querySelector(location.hash); if(d&&d.tagName==='DETAILS'){d.open=true;}}
})();

